int cp_lca_query(int u, int v, int max_log, const int* depth, const int* up) {
    if (depth[u] < depth[v]) {
        int tmp = u; u = v; v = tmp;
    }
    for (int j = max_log - 1; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) {
            u = up[u * max_log + j];
        }
    }
    if (u == v) return u;
    for (int j = max_log - 1; j >= 0; j--) {
        if (up[u * max_log + j] != up[v * max_log + j]) {
            u = up[u * max_log + j];
            v = up[v * max_log + j];
        }
    }
    return up[u * max_log + 0];
}

