                    printf("Enter %d integers: ", n);
                    for (int i = 0; i < n; i++) scanf("%d", &orig[i]);
                    clear_input();
                    u_len = compress_coords(orig, n, unique_arr, compressed);
                    printf("Compressed %d values into %d distinct ranks.\n", n, u_len);
                } else {
                    clear_input();
                }
                break;
