#include <stdio.h>
#include <stdlib.h>

#define MAX_SIEVE 1000000

static int spf[MAX_SIEVE + 1];
static int is_prime[MAX_SIEVE + 1];

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static void build_sieve(int limit) {
    if (limit > MAX_SIEVE) limit = MAX_SIEVE;
    for (int i = 0; i <= limit; i++) {
        is_prime[i] = 1;
        spf[i] = i;
    }
    is_prime[0] = is_prime[1] = 0;
    spf[0] = spf[1] = 0;
    for (int i = 2; (long long)i * i <= limit; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= limit; j += i) {
                if (is_prime[j]) {
                    is_prime[j] = 0;
                    spf[j] = i;
                }
            }
        }
    }
}

static void factorize_spf(int n) {
    if (n <= 1) {
        printf("%d has no prime factors.\n", n);
        return;
    }
    printf("%d = ", n);
    int first = 1;
    while (n > 1) {
        int p = spf[n];
        int count = 0;
        while (n % p == 0) {
            count++;
            n /= p;
        }
        if (!first) printf(" * ");
        if (count > 1) printf("%d^%d", p, count);
        else printf("%d", p);
        first = 0;
    }
    putchar('\n');
}

static int count_primes_range(int l, int r) {
    if (l < 2) l = 2;
    int count = 0;
    for (int i = l; i <= r; i++) {
        if (is_prime[i]) count++;
    }
    return count;
}

static int euler_totient(int n) {
    int res = n;
    while (n > 1) {
        int p = spf[n];
        while (n % p == 0) n /= p;
        res -= res / p;
    }
    return res;
}

