        printf("4. List Primes in Range [L, R]\n");
        printf("5. Euler's Totient Function phi(N)\n");
        printf("6. Rebuild Sieve with New Limit (<= %d)\n", MAX_SIEVE);
        printf("7. Solve CF Multi-Testcases (T Cases)\n");
        printf("0. Exit\n");
