    if (r < 0 || r > n) return 0;
    return (fact[n] * inv_fact[n - r]) % MOD;
}

static ll catalan_number(int n) {
    ll c = query_ncr(2 * n, n);
    return (c * mod_inv(n + 1)) % MOD;
}

