    for (int i = 1; i <= r; i++) {
        for (int j = 1; j <= c; j++) {
            ll val;
            scanf("%lld", &val);
            pref[i][j] = val + pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1];
        }
    }
    printf("Enter %d subgrid queries (1-indexed r1 c1 r2 c2):\n", q);
