#define MAX_V 1000
#define MAX_E 4000
#define INF_DIST 1000000000

typedef struct {
    int to;
    int weight;
    int next;
} Edge;

static int head[MAX_V + 1];
static Edge edges[MAX_E];
static int edge_count = 0;
static int dist[MAX_V + 1];
static int parent[MAX_V + 1];

static int deque[2 * MAX_V + 5];
static int dq_head = MAX_V, dq_tail = MAX_V - 1;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

static void add_edge(int u, int v, int w) {
    edges[edge_count].to = v;
    edges[edge_count].weight = w;
    edges[edge_count].next = head[u];
    head[u] = edge_count++;
}

static void zero_one_bfs(int src, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = INF_DIST;
        parent[i] = -1;
    }
    dq_head = MAX_V;
    dq_tail = MAX_V - 1;

    dist[src] = 0;
    deque[++dq_tail] = src;

    while (dq_head <= dq_tail) {
        int u = deque[dq_head++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int w = edges[e].weight;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                parent[v] = u;
                if (w == 0) {
                    deque[--dq_head] = v;
                } else {
                    deque[++dq_tail] = v;
                }
            }
        }
    }
}

