    if (dist[target] == INF_DIST) {
        printf("Unreachable.\n");
        return;
    }
    int path[MAX_V];
    int len = 0;
    for (int cur = target; cur != -1; cur = parent[cur]) {
        path[len++] = cur;
    }
    printf("Path (distance %d): ", dist[target]);
    for (int i = len - 1; i >= 0; i--) {
        printf("%d%s", path[i], (i == 0) ? "" : " -> ");
    }
    putchar('\n');
}

